module ice_cream_optimizer (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] n,\n    input [7:0] k,\n    input [7:0] a,\n    input [7:0] b,\n    input [7:0] t [0:7],\n    input [7:0] u [0:7][0:7],\n    output reg [15:0] result,\n    output reg done\n);\n\n// State declarations\nlocalparam [2:0] IDLE = 3'd0;\nlocalparam [2:0] COMPUTE_GRAPH = 3'd1;\nlocalparam [2:0] FIND_MAX_PATH = 3'd2;\nlocalparam [2:0] CALC_RATIO = 3'd3;\nlocalparam [2:0] FINISH = 3'd4;\n\nreg [2:0] state;\nreg [7:0] current_scoop;\nreg [15:0] best_tastiness;\nreg [15:0] max_ratio;\nreg [7:0] current_flavor;\nreg [15:0] current_cost;\n\n// Graph representation (8x8 matrix with 16-bit Q8.8)\nreg signed [15:0] edge_weight [0:7][0:7];\nreg signed [15:0] node_weight [0:7];\n\n// Indices and counters\ninteger i, j;\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        result <= 16'd0;\n        done <= 1'b0;\n        current_scoop <= 8'd0;\n        best_tastiness <= 16'd0;\n        max_ratio <= 16'd0;\n        current_flavor <= 8'd0;\n        current_cost <= 16'd0;\n        \n        // Array initializations\n        for (i = 0; i < 8; i = i + 1) begin\n            for (j = 0; j < 8; j = j + 1) begin\n                edge_weight[i][j] <= 16'd0;\n            end\n            node_weight[i] <= 16'd0;\n        end\n    end else begin\n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                result <= 16'd0;\n                current_scoop <= 8'd0;\n                best_tastiness <= 16'd0;\n                max_ratio <= 16'd0;\n                if (start) begin\n                    state <= COMPUTE_GRAPH;\n                    \n                    // Precompute node weights\n                    for (i = 0; i < 8; i = i + 1) begin\n                        if (i < k) begin\n                            node_weight[i] <= {t[i], 8'd0};  // Q8.8 format\n                        end else begin\n                            node_weight[i] <= 16'd0;\n                        end\n                    end\n                    \n                    // Precompute edge weights\n                    for (i = 0; i < 8; i = i + 1) begin\n                        for (j = 0; j < 8; j = j + 1) begin\n                            if (i < k && j < k) begin\n                                edge_weight[i][j] <= node_weight[j] + {u[j][i], 8'd0};  // Q8.8\n                            end else begin\n                                edge_weight[i][j] <= 16'd0;\n                            end\n                        end\n                    end\n                end\n            end\n            \n            COMPUTE_GRAPH: begin\n                state <= FIND_MAX_PATH;\n                current_scoop <= 8'd1;\n            end\n            \n            FIND_MAX_PATH: begin\n                // Simplified tastiness tracking - in reality you'd use DP\n                if (current_scoop <= n) begin\n                    if (current_scoop == 8'd1) begin\n                        // Track maximum single flavor tastiness\n                        best_tastiness <= 16'd0;\n                        for (i = 0; i < 8; i = i + 1) begin\n                            if (i < k && node_weight[i] > best_tastiness) begin\n                                best_tastiness <= node_weight[i];\n                            end\n                        end\n                    end else if (current_scoop == 8'd2) begin\n                        // Track maximum pair\n                        best_tastiness <= 16'd0;\n                        for (i = 0; i < 8; i = i + 1) begin\n                            for (j = 0; j < 8; j = j + 1) begin\n                                if (i < k && j < k && (node_weight[i] + edge_weight[i][j]) > best_tastiness) begin\n                                    best_tastiness <= node_weight[i] + edge_weight[i][j];\n                                end\n                            end\n                        end\n                    end\n                    state <= CALC_RATIO;\n                end else begin\n                    state <= FINISH;\n                end\n            end\n            \n            CALC_RATIO: begin\n                // Calculate cost in Q8.8\n                current_cost <= {8'd0, a} * {8'd0, current_scoop} + {8'd0, b};\n                \n                // Calculate ratio (if cost > 0)\n                if (current_cost != 16'd0 && best_tastiness != 16'd0) begin\n                    if (best_tastiness / current_cost > max_ratio) begin\n                        max_ratio <= best_tastiness / current_cost;\n                    end\n                end\n                \n                if (current_scoop >= n) begin\n                    state <= FINISH;\n                end else begin\n                    current_scoop <= current_scoop + 8'd1;\n                    state <= FIND_MAX_PATH;\n                end\n            end\n            \n            FINISH: begin\n                result <= max_ratio;\n                done <= 1'b1;\n                state <= IDLE;\n            end\n            \n            default: state <= IDLE;\n        endcase\n    end\nend\n\nendmodule